const esc = value => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;");

const arrow = (href, label, className = "p-link") => `<a class="${className}" href="${href}">${esc(label)}<span aria-hidden="true">↗</span></a>`;
const label = text => `<span class="p-label">${esc(text)}</span>`;
const figure = (number, title, body, note = "", className = "") => `<figure class="p-exhibit ${className}" role="img" aria-label="Exhibit ${number}: ${esc(title)}"><figcaption><span>Exhibit ${String(number).padStart(2, "0")}</span><strong>${esc(title)}</strong></figcaption>${body}${note ? `<p class="p-exhibit-note">${esc(note)}</p>` : ""}</figure>`;

const recordPath = item => `/track-record/${item.slug}`;
const usePath = item => item.slug === "ai-commerce-command-center" ? "/ai-commerce" : item.slug === "career-runway-ai" ? "/career-runway" : `/use-cases/${item.slug}`;

const miniFlow = items => `<div class="p-mini-flow">${items.map((item, index) => `<span><b>${String(index + 1).padStart(2, "0")}</b>${esc(item)}</span>`).join("")}</div>`;

const operatingRail = records => `<div class="p-record-rail">${records.map((item, index) => `<a href="${recordPath(item)}"><span class="p-record-no">${String(index + 1).padStart(2, "0")}</span><span class="p-record-copy"><small>${esc(item.period)}</small><strong>${esc(item.name)}</strong><em>${esc(item.role)}</em></span><span class="p-record-arrow" aria-hidden="true">↗</span></a>`).join("")}</div>`;

const homeCasePreview = item => {
  if (item.slug === "leading-saudi-bank-commerce-ecosystem") return `<a class="p-case-feature p-case-bank" href="${usePath(item)}"><div class="p-case-copy">${label("Banking and commerce · Flagship blueprint")}<h3>${esc(item.title)}</h3><p>Move the bank upstream from payment authorization into purchase intent, eligible value and attributable merchant spend.</p>${miniFlow(["Intent", "Eligibility", "Value", "Merchant", "Spend"])}<span class="p-inline-link">Open the case <i aria-hidden="true">↗</i></span></div><div class="p-case-art p-bank-art" aria-hidden="true"><div class="p-bank-ring ring-a"></div><div class="p-bank-ring ring-b"></div><div class="p-bank-hub">Bank<br>commerce<br>layer</div><span class="node-a">Customer</span><span class="node-b">Merchant</span><span class="node-c">Cards</span><span class="node-d">Loyalty</span></div></a>`;
  if (item.slug === "retail-group-transformation") return `<a class="p-case-feature p-case-retail" href="${usePath(item)}"><div class="p-case-copy">${label("Retail transformation · Operating case")}<h3>${esc(item.title)}</h3><p>Connect store economics, ageing inventory and cash into one management agenda.</p><div class="p-mini-waterfall" aria-hidden="true"><span style="--h:88%">Sales</span><span style="--h:72%">Margin</span><span style="--h:48%">Stock</span><span style="--h:61%">Cash</span></div><span class="p-inline-link">Open the case <i aria-hidden="true">↗</i></span></div></a>`;
  return `<a class="p-case-feature p-case-ai" href="${usePath(item)}"><div class="p-case-copy">${label("Applied AI · Product")}<h3>${esc(item.title)}</h3><p>A supervised operating layer for commerce signals, exceptions and approved action.</p><div class="p-mini-console" aria-hidden="true"><div><span>Exception queue</span><b>Order risk</b><i></i><i></i></div><div><span>Recommended action</span><b>Hold and review</b><button>Approval required</button></div></div><span class="p-inline-link">Open the product <i aria-hidden="true">↗</i></span></div></a>`;
};

const insightPreview = (item, index) => `<a class="p-insight-line" href="/insights/${item.slug}"><span>${String(index + 1).padStart(2, "0")}</span><div><small>${esc(item.visual.join(" · "))}</small><strong>${esc(item.title)}</strong><p>${esc(item.lead)}</p></div><i aria-hidden="true">↗</i></a>`;

export function pilotHome({ trackRecords, useCases, aiProjects, insights }) {
  const saudi = useCases.find(item => item.slug === "leading-saudi-bank-commerce-ecosystem");
  const retail = useCases.find(item => item.slug === "retail-group-transformation");
  const command = aiProjects.find(item => item.slug === "ai-commerce-command-center");
  return `<section class="p-hero p-home-hero"><div class="p-shell p-home-hero-grid"><div class="p-hero-copy">${label("Muhammad Haris Aslam · GCC operator and business builder")}<h1>Build businesses.<br>Fix economics.<br>Scale what works.</h1><p>Operating leadership across commerce, retail, marketplaces, enterprise technology and applied AI.</p><div class="p-hero-actions">${arrow("/track-record", "Track record", "p-button p-button-light")}${arrow("/use-cases", "Use cases", "p-button p-button-ghost")}</div><div class="p-hero-proof"><span><b>GCC</b>market building</span><span><b>Operator</b>direct responsibility</span><span><b>Builder</b>commercial and technical depth</span></div></div><figure class="p-portrait"><img src="/assets/haris-aslam.webp" alt="Muhammad Haris Aslam" width="717" height="960"><figcaption><span>Doha · GCC</span><strong>Business building, transformation and investment</strong></figcaption></figure></div></section>
  <section class="p-section p-record-section"><div class="p-shell"><header class="p-section-head"><div>${label("Selected operating record")}<h2>Building, launching and transforming businesses.</h2></div><p>Selected roles and ventures where Haris held direct responsibility for building, growth, transformation or investment.</p></header>${operatingRail(trackRecords)}</div></section>
  <section class="p-value-band"><div class="p-shell"><header>${label("Where I create value")}<h2>Business ambition is useful only when the model can earn, operate and scale.</h2></header><div class="p-value-system"><div><span>01</span><h3>Build</h3><p>Turn a market need into a proposition, commercial model, operating system and launch plan.</p><small>Venture design · Market launch · Product economics</small></div><div><span>02</span><h3>Transform</h3><p>Connect margin, inventory, customer experience, technology and governance to one value-creation plan.</p><small>Turnaround · Working capital · Digital transformation</small></div><div><span>03</span><h3>Scale</h3><p>Prove contribution, strengthen decision rights and add markets, channels or automation without losing control.</p><small>GCC growth · Operating cadence · AI-enabled scale</small></div></div></div></section>
  <section class="p-section p-selected-cases"><div class="p-shell"><header class="p-section-head"><div>${label("Selected flagship use cases")}<h2>Commercial cases built for executive discussion.</h2></div><p>Each case connects customer demand to economics, technology, governance and an implementable operating model.</p></header><div class="p-case-mosaic">${homeCasePreview(saudi)}${homeCasePreview(retail)}${homeCasePreview(command)}</div><div class="p-section-link">${arrow("/use-cases", "Explore the use-case library")}</div></div></section>
  <section class="p-transformation-band"><div class="p-shell p-transformation-grid"><div class="p-transformation-copy">${label("Value-creation discipline")}<h2>A transformation has to reach cash, customers and operating decisions.</h2><p>Strategy sits inside the operating rhythm. The management view needs to show where value is expected, which system produces the fact, who has authority to act and how the result will be measured.</p>${arrow("/use-cases/retail-group-transformation", "See the retail transformation case", "p-link p-link-light")}</div><div class="p-transformation-model" role="img" aria-label="Transformation model connecting diagnosis, economics, operating change, technology and measured result"><div class="p-model-spine"><span>Diagnosis</span><span>Commercial case</span><span>Operating change</span><span>Technology</span><span>Evidence</span></div><div class="p-model-output"><small>Management outcome</small><strong>Margin</strong><strong>Cash</strong><strong>Service</strong><strong>Growth</strong></div></div></div></section>
  <section class="p-section p-ai-preview"><div class="p-shell"><header class="p-section-head"><div>${label("AI & Transformation")}<h2>Products and workflows designed around real operating decisions.</h2></div><p>AI prepares evidence, ranks approved options and moves work through controlled steps. People retain authority over money, risk and customer consequence.</p></header><div class="p-product-stage"><div class="p-command-preview"><div class="p-ui-top"><span>AI Commerce Command Center</span><small>Supervisor view</small></div><div class="p-command-layout"><aside><b>Signals</b><span>Orders</span><span>Inventory</span><span>Sellers</span><span>Care</span><span>Finance</span></aside><main><div class="p-ui-stat"><span>Exceptions requiring review</span><strong>12</strong></div><div class="p-ui-chart"><i style="--h:34%"></i><i style="--h:62%"></i><i style="--h:45%"></i><i style="--h:81%"></i><i style="--h:56%"></i><i style="--h:71%"></i></div><div class="p-ui-action"><span>Recommended action</span><strong>Hold seller payout and review fulfilment evidence</strong><button>Human approval</button></div></main></div></div><div class="p-product-index">${[...aiProjects, useCases.find(item => item.slug === "aeofind")].map((item, index) => `<a href="${usePath(item)}"><span>0${index + 1}</span><div><small>${esc(item.type)}</small><strong>${esc(item.title)}</strong></div><i aria-hidden="true">↗</i></a>`).join("")}</div></div></div></section>
  <section class="p-section p-venture-strip"><div class="p-shell p-venture-grid"><div>${label("Investment and venture building")}<h2>Capital follows a model that can be explained and governed.</h2></div><div><p>Venture formation, investment assessment and fundraising work connected to businesses Haris directly led. The focus is the use of capital, downside exposure, operating readiness and the evidence needed before a scale decision.</p>${arrow("/track-record/salman-miraq", "Salman Corporation / Miraq Lifestyle")}</div></div></section>
  <section class="p-section p-insight-section"><div class="p-shell"><header class="p-section-head"><div>${label("Insights")}<h2>Notes on commercial models and operating decisions.</h2></div>${arrow("/insights", "View all insights")}</header><div class="p-insight-list">${insights.slice(0, 4).map(insightPreview).join("")}</div></div></section>
  <section class="p-contact-band"><div class="p-shell p-contact-grid"><div>${label("About")}<h2>Operator, builder and transformation leader based in Doha.</h2><p>Haris works across the decisions that turn an idea into an operating business: customer proposition, economics, technology, organization and execution.</p>${arrow("/about", "About Haris", "p-link p-link-light")}</div><div>${label("Contact")}<h2>Start with the business problem.</h2><p>A short note on the market, the economics and the decision that needs to be made is enough.</p>${arrow("/contact", "Get in touch", "p-button p-button-light")}</div></div></section>`;
}

const recordVisual = item => {
  const visuals = {
    roumaan: `<div class="p-story-diagram p-story-commerce">${miniFlow(["Demand", "Catalogue", "Order", "Fulfilment", "Learning"])}</div>`,
    "upapp-factory": `<div class="p-story-diagram p-story-studio">${miniFlow(["Requirement", "Design", "Build", "Deploy", "Support"])}</div>`,
    "floward-oman": `<div class="p-story-diagram p-story-floward"><span>Local setup</span><span>Assortment</span><span>Fulfilment</span><span>Occasion trading</span><b>Oman launch</b></div>`,
    "salman-miraq": `<div class="p-story-diagram p-story-investment"><div><span>Core retail</span><b>Margin and cash reset</b></div><div><span>Portfolio</span><b>Capital choices</b></div><div><span>New ventures</span><b>Investment gates</b></div></div>`
  };
  return visuals[item.slug] || "";
};

export function pilotTrack({ trackRecords }) {
  return `<section class="p-hero p-track-hero"><div class="p-shell p-track-hero-grid"><div>${label("Track record · Direct operating responsibility")}<h1>Building, launching and transforming businesses.</h1><p>Selected operating roles and ventures where Haris held direct responsibility for building, growth, transformation or investment.</p></div><aside><span>Operating arc</span><strong>Founder-led commerce</strong><i></i><strong>Digital product delivery</strong><i></i><strong>Country launch</strong><i></i><strong>Retail and investment transformation</strong><i></i><strong>Enterprise scale</strong></aside></div></section>
  <section class="p-current-mandate"><div class="p-shell"><span>Current mandate</span><strong>Strategic Digital Commerce - Major Telecom Operator, Qatar</strong><p>Currently working on strategic digital-commerce, marketplace and operating-model transformation within a major telecom operator in Qatar.</p></div></section>
  <section class="p-track-index"><div class="p-shell"><div class="p-track-index-head"><span>Selected named businesses and roles</span><p>The record is organized around mandates and operating systems rather than job titles.</p></div>${operatingRail(trackRecords)}</div></section>
  <section class="p-record-stories">${trackRecords.map((item, index) => `<article class="p-record-story ${index % 2 ? "is-light" : "is-dark"}"><div class="p-shell p-record-story-grid"><header><span>${String(index + 1).padStart(2, "0")} · ${esc(item.period)}</span><h2>${esc(item.name)}</h2><p>${esc(item.role)} · ${esc(item.geography)}</p></header><div class="p-story-copy"><h3>${esc(item.mandate)}</h3><p>${esc(item.built)}</p><div class="p-story-meta"><div><span>Commercial model</span><p>${esc(item.commercial)}</p></div><div><span>Technology and operations</span><p>${esc(item.technology)}</p></div></div>${arrow(recordPath(item), `Read the ${item.name} operating story`, index % 2 ? "p-link" : "p-link p-link-light")}</div>${recordVisual(item)}</div></article>`).join("")}</section>
  <section class="p-capital-band"><div class="p-shell p-capital-grid"><div>${label("Capital and investment")}<h2>Operating evidence comes before the funding story.</h2></div><div><p>Where ventures required investment or fundraising, the work connected the capital ask to commercial rights, cash requirements, operating readiness, downside exposure and the milestones that would release the next commitment.</p><div class="p-capital-path"><span>Commercial rights</span><span>Base and downside case</span><span>Capital required</span><span>Operating gate</span><span>Board decision</span></div></div></div></section>`;
}

const currentBankJourney = () => figure(1, "The bank enters after the commercial decision", `<div class="p-current-journey"><div class="p-journey-zone customer-zone"><span>Customer decision</span><div><b>Need emerges</b><small>Purchase intent forms outside the bank</small></div><div><b>Category and product chosen</b><small>Alternatives narrow</small></div><div><b>Merchant selected</b><small>Price and service determine preference</small></div></div><div class="p-journey-zone bank-late-zone"><span>Bank appears</span><div><b>Payment authorization</b><small>The commercial choice is already made</small></div><div><b>Points posted</b><small>Value arrives after checkout</small></div></div><aside><strong>Lost influence</strong><span>Intent</span><span>Merchant choice</span><span>Wallet share</span><span>Offer funding</span></aside></div>`, "Authorization data explains where the customer spent. It cannot show which value would have changed the choice.", "p-exhibit-dark");

const futureBankJourney = () => figure(2, "A commerce-enabled journey begins at declared intent", `<div class="p-future-journey"><div class="p-future-track"><span>01</span><strong>Declare a purchase need</strong><p>The customer selects a category or planned purchase inside an authenticated bank channel.</p></div><div class="p-future-track"><span>02</span><strong>Resolve eligibility</strong><p>Card, loyalty and finance systems confirm which value the customer may use.</p></div><div class="p-future-track"><span>03</span><strong>Rank relevant value</strong><p>AI orders only approved merchant and bank options, with reason codes.</p></div><div class="p-future-track"><span>04</span><strong>Explain and hand off</strong><p>The bank explains value and sends the customer to the merchant.</p></div><div class="p-future-track"><span>05</span><strong>Match the transaction</strong><p>Handoff, authorization, return and benefit events enter one ledger.</p></div><div class="p-future-track"><span>06</span><strong>Measure incrementality</strong><p>A control cohort tests whether the journey changed spend or merely attributed it.</p></div></div>`, "The merchant keeps responsibility for product, price, checkout, fulfilment and returns.");

const bankEcosystem = () => figure(3, "Bank, merchant and customer ecosystem", `<div class="p-ecosystem"><svg viewBox="0 0 1000 460" aria-hidden="true"><path d="M500 230 L180 90 M500 230 L820 90 M500 230 L180 370 M500 230 L820 370"/><path class="secondary" d="M180 90 L820 90 M180 370 L820 370"/></svg><div class="p-eco-hub"><small>Orchestration</small><strong>Bank commerce layer</strong><span>Intent · Eligibility · Ranking · Attribution</span></div><div class="p-eco-node eco-customer"><small>Customer</small><strong>Need, consent and choice</strong><span>Controls the purchase decision</span></div><div class="p-eco-node eco-merchant"><small>Merchant</small><strong>Product and service</strong><span>Owns retail execution</span></div><div class="p-eco-node eco-products"><small>Bank products</small><strong>Cards, loyalty and finance</strong><span>Resolve permitted value</span></div><div class="p-eco-node eco-control"><small>Bank operations</small><strong>Settlement and control</strong><span>Reconciles the result</span></div></div>`, "Each party keeps a clear role. The bank coordinates value without taking over retail service.");

const economicsWaterfall = () => figure(4, "Commercial value pools and cost deductions", `<div class="p-waterfall"><div class="p-waterfall-axis"><span>Higher modeled contribution</span><span>Baseline</span></div><div class="p-waterfall-bars"><div class="add" style="--from:0;--size:92"><span>Incremental card contribution</span><i></i></div><div class="add" style="--from:18;--size:74"><span>Merchant funding</span><i></i></div><div class="add" style="--from:33;--size:58"><span>Loyalty and eligible finance value</span><i></i></div><div class="cost" style="--from:31;--size:42"><span>Customer benefit and acquisition</span><i></i></div><div class="cost" style="--from:20;--size:35"><span>Platform and service</span><i></i></div><div class="cost" style="--from:14;--size:28"><span>Risk, returns and settlement</span><i></i></div><div class="result" style="--from:0;--size:63"><span>Net incremental contribution</span><i></i></div></div></div><div class="p-economics-equation"><span>Eligible demand</span><b>×</b><span>Conversion</span><b>×</b><span>Incremental basket</span><b>×</b><span>Net value rate</span><b>−</b><span>Full cost to serve</span><b>=</b><strong>Net contribution</strong></div>`, "Conceptual economics only. Bar heights show the structure of the model, not a forecast or achieved result.");

const bankArchitecture = () => figure(5, "Technology and data architecture", `<div class="p-bank-architecture"><div class="p-arch-layer experience"><span>Experience</span><div><b>Bank app</b><b>Intent entry</b><b>Offer explanation</b><b>Merchant handoff</b></div></div><div class="p-arch-layer decision"><span>Eligibility and decisioning</span><div><b>Card rules</b><b>Loyalty rules</b><b>Finance eligibility</b><b>AI ranking</b></div></div><div class="p-arch-layer services"><span>Commerce services</span><div><b>Merchant offers</b><b>Handoff tokens</b><b>Campaign rules</b><b>Service metadata</b></div></div><div class="p-arch-layer records"><span>Systems of record</span><div><b>Cards</b><b>Loyalty</b><b>Transactions</b><b>Merchant checkout</b><b>Returns</b></div></div><div class="p-arch-layer control"><span>Control and measurement</span><div><b>Consent ledger</b><b>Attribution</b><b>Settlement</b><b>Model logs</b><b>Audit</b></div></div></div>`, "Live balances, eligibility, transactions and returns stay in authoritative systems. The commerce layer coordinates them through controlled interfaces.", "p-exhibit-dark");

const aiDecisioning = () => figure(6, "AI ranks approved value; it does not create eligibility", `<div class="p-ai-decision"><div class="p-ai-inputs"><span>Declared intent</span><span>Eligible cards</span><span>Loyalty balance</span><span>Approved offers</span><span>Merchant service</span></div><div class="p-policy-gate"><small>Deterministic policy gate</small><strong>Permitted options only</strong><span>Consent · Credit rules · Campaign terms · Frequency</span></div><div class="p-ranking-engine"><small>AI decisioning</small><strong>Rank next best value</strong><div><span>Relevance</span><span>Customer value</span><span>Merchant quality</span><span>Commercial contribution</span></div></div><div class="p-ai-output"><span>Ranked option</span><span>Reason code</span><span>Confidence</span><span>Alternative</span></div><aside><b>Human control</b><p>Teams can suppress a merchant, campaign, feature or model version. Credit, rewards liability and consent remain outside model authority.</p></aside></div>`, "The model orders permitted options. It cannot approve finance, alter product eligibility or override customer consent.");

const bankOperatingModel = () => figure(7, "Operating model and decision rights", `<div class="p-operating-model"><div class="p-op-column"><span>Customer and channel</span><b>Declare need</b><b>Review value</b><b>Choose merchant</b><b>Complete purchase</b></div><div class="p-op-column accent"><span>Commerce product</span><b>Own journey</b><b>Set ranking objective</b><b>Read economics</b><b>Coordinate pilot</b></div><div class="p-op-column"><span>Merchant operations</span><b>Load offers</b><b>Maintain service</b><b>Resolve retail issues</b><b>Fund benefits</b></div><div class="p-op-column"><span>Cards and loyalty</span><b>Resolve eligibility</b><b>Execute benefit</b><b>Match and reverse</b><b>Reconcile liability</b></div><div class="p-op-column control"><span>Risk, finance and data</span><b>Approve policy</b><b>Review model</b><b>Reconcile funding</b><b>Release scale gate</b></div></div><div class="p-operating-cadence"><span><b>Daily</b>Exceptions and service</span><span><b>Weekly</b>Commercial and pilot review</span><span><b>Monthly</b>Risk, model and finance</span><span><b>Gate</b>Scale, narrow or stop</span></div>`, "One product owner coordinates the journey. Specialist teams retain authority for regulated, financial and retail decisions.");

const bankRoadmap = () => figure(8, "Twelve-month implementation roadmap", `<div class="p-roadmap"><div class="p-roadmap-scale"><span>Month 0</span><span>Month 3</span><span>Month 6</span><span>Month 9</span><span>Month 12</span></div><div class="p-roadmap-lane"><strong>Commercial</strong><span style="--start:1;--span:3">Categories, merchants and funding</span><span style="--start:4;--span:3">Pilot economics</span><span style="--start:7;--span:6">Selective merchant scale</span></div><div class="p-roadmap-lane"><strong>Experience</strong><span style="--start:1;--span:2">Journey design</span><span style="--start:3;--span:3">Build and employee test</span><span style="--start:6;--span:3">Customer pilot</span><span style="--start:9;--span:4">Category expansion</span></div><div class="p-roadmap-lane"><strong>Data and technology</strong><span style="--start:1;--span:3">Eligibility, offers and events</span><span style="--start:4;--span:3">Attribution and settlement</span><span style="--start:7;--span:6">Automation and self-service</span></div><div class="p-roadmap-lane"><strong>Control</strong><span style="--start:1;--span:2">Consent and policy</span><span style="--start:3;--span:4">Testing and audit</span><span style="--start:7;--span:2">Scale gate 1</span><span style="--start:10;--span:3">Scale gate 2</span></div></div>`, "Every expansion step requires commercial contribution, acceptable service, clean reconciliation and risk approval.", "p-exhibit-dark");

const kpiCockpit = () => `<div class="p-kpi-cockpit" role="img" aria-label="Executive KPI cockpit"><div><span>Reach and relevance</span><b>Eligible customers</b><b>Intent starts</b><b>Offer relevance</b><b>Frequency caps</b></div><div><span>Journey</span><b>Merchant handoff</b><b>Completed conversion</b><b>Repeat use</b><b>Service failure</b></div><div><span>Incrementality</span><b>Control lift</b><b>Wallet recapture</b><b>Incremental spend</b><b>Category lift</b></div><div><span>Economics</span><b>Merchant funding</b><b>Reward cost</b><b>Service cost</b><b>Net contribution</b></div><div><span>Trust and control</span><b>Consent withdrawal</b><b>Eligibility errors</b><b>Settlement breaks</b><b>Model overrides</b></div></div>`;

export function pilotSaudi({ item }) {
  return `<section class="p-bank-hero"><img src="/assets/bank-commerce-concept.png" alt="Concept visualization of a card, customer intent, merchant value and completed transaction" width="1680" height="945"><div class="p-bank-hero-shade"></div><div class="p-shell p-bank-hero-copy"><nav class="p-pilot-crumb" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/use-cases">Use cases</a><span>/</span><b>Saudi bank intelligent-commerce ecosystem</b></nav>${label("Flagship strategy blueprint · Saudi Arabia · Modeled impact")}<h1>Move the bank upstream into purchase intent.</h1><p>A commerce ecosystem that connects eligible card, loyalty, merchant and finance value before checkout, then measures whether the journey changed customer spend.</p><div class="p-bank-thesis"><span><b>Problem</b>The bank arrives after the customer has chosen.</span><span><b>Opportunity</b>Declared intent creates an earlier point of influence.</span><span><b>Control</b>Eligibility, consent and financial authority stay with bank systems.</span></div></div></section>
  <nav class="p-case-nav" aria-label="Case chapters"><div class="p-shell"><a href="#board-question">Board question</a><a href="#journey">Customer journey</a><a href="#ecosystem">Ecosystem</a><a href="#economics">Economics</a><a href="#architecture">Technology and AI</a><a href="#operating-model">Operating model</a><a href="#roadmap">Roadmap</a><a href="#impact">Impact</a></div></nav>
  <section class="p-case-section p-case-opening" id="board-question"><div class="p-shell p-case-two"><div class="p-case-copy-long">${label("Executive summary")}<h2>The bank owns payment rails and customer relationships, but usually enters the buying journey too late.</h2><p>By the time a card authorization reaches the bank, the customer has already decided what to buy, selected a merchant and chosen a payment route. The bank can approve the transaction and post points, yet it has little influence over the commercial choice that created the spend. Offer directories and post-purchase rewards sit downstream as well. They may reward activity, but they do not consistently connect a current customer need to relevant, eligible value.</p><p>The strategy is to enter at declared purchase intent without turning the bank into a retailer. A customer begins with a need such as travel, electronics, home, education or a planned large purchase. The bank resolves which cards, rewards, merchant benefits or instalment routes are permitted for that customer. AI then ranks the approved options and explains why they are relevant. The merchant retains responsibility for product, price, stock, checkout, fulfilment and returns.</p><p>The value case combines incremental card contribution, merchant-funded demand, better use of loyalty assets, eligible finance value and stronger engagement with the bank's owned channels. Those pools only matter after benefit cost, merchant acquisition, platform integration, customer care, fraud, returns, settlement and operating capacity are deducted. Attributed spend is not treated as incremental until a control cohort shows a behavioural difference.</p><p>This is a strategy blueprint. No bank implementation, revenue result or customer uplift is claimed. The first management decision is whether a controlled 90-day pilot can prove relevance, merchant service, clean attribution, funding reconciliation and positive modeled contribution at the same time.</p></div><aside class="p-board-box"><span>Board decision</span><h3>Should the bank influence purchase intent before checkout?</h3><dl><div><dt>Build</dt><dd>A narrow intent and value layer inside an authenticated channel</dd></div><div><dt>Avoid</dt><dd>A general marketplace, copied merchant catalogue or new credit engine</dd></div><div><dt>Prove</dt><dd>Incremental spend, contribution, service quality and control</dd></div><div><dt>Gate</dt><dd>Scale only after returns, rewards and merchant funding reconcile</dd></div></dl></aside></div></section>
  <section class="p-case-section p-case-light" id="journey"><div class="p-shell"><header class="p-case-heading">${label("Business problem")}<h2>Purchase intent is created before payment authorization.</h2><div><p>Customers form a need, compare categories, narrow products and choose merchants across search, social media, marketplaces, brand sites and physical retail. The bank sees the transaction at the end of that sequence. Transaction history can describe past spend, but it cannot reliably explain the alternatives considered or the benefit that would have changed the choice.</p><p>The commercial gap is the distance between a bank's valuable assets and the moment those assets can influence behaviour. Cards, loyalty balances, merchant relationships, trusted identity and eligible finance may all exist, yet the customer experiences them as separate products. The opportunity is to coordinate them around a current need.</p></div></header>${currentBankJourney()}${futureBankJourney()}<div class="p-case-text-grid"><div><h3>Cardholder segmentation</h3><p>Segmentation begins with the declared category, value sensitivity, existing product eligibility, location or fulfilment feasibility, loyalty balance, recent engagement and consented transaction patterns. Protected characteristics and unrelated sensitive data have no place in offer ranking. The pilot should use a small set of commercially meaningful segments that product, risk and merchant teams can explain.</p></div><div><h3>Cardholder value</h3><p>The customer should see a short list of permitted options, not another campaign catalogue. Each option explains the benefit, conditions, merchant, payment route and whether rewards or existing instalment eligibility apply. The customer keeps control of the final purchase and can withdraw consent for the commerce journey.</p></div><div><h3>Merchant value</h3><p>Merchants receive qualified demand from identifiable customer needs rather than broad campaign traffic. They fund value against completed transactions or defined campaign terms. In return, the bank requires reliable offer data, recognizable transaction descriptors, service ownership, return events and settlement evidence.</p></div></div></div></section>
  <section class="p-case-section p-case-dark" id="ecosystem"><div class="p-shell"><header class="p-case-heading">${label("Solution design")}<h2>A coordination layer, not a bank-owned retailer.</h2><div><p>The customer layer captures intent and explains eligible value. The product layer resolves card, loyalty and finance rules. The merchant layer manages funded offers, handoff and service metadata. The measurement layer connects intent, offer view, merchant visit, authorization, return and settlement.</p><p>Role clarity protects the model. The merchant owns the retail transaction. The bank owns financial eligibility, consent, attribution and settlement. AI can rank permitted options but cannot create an entitlement, approve credit or change rewards liability.</p></div></header>${bankEcosystem()}<div class="p-principle-row"><span><b>Customer</b>Need, consent and choice</span><span><b>Bank</b>Eligibility, value and control</span><span><b>Merchant</b>Product, service and funded demand</span><span><b>Shared ledger</b>Attribution, returns and settlement</span></div></div></section>
  <section class="p-case-section p-case-light" id="economics"><div class="p-shell"><header class="p-case-heading">${label("Commercial model")}<h2>Payment volume is an activity measure. The decision rests on net incremental contribution.</h2><div><p>The first value pool is spend that moves to the bank's card portfolio or occurs more often because relevant value appeared before checkout. The second is merchant funding: a fixed benefit, campaign contribution or completed-transaction acquisition fee tied to qualified demand. Loyalty and eligible finance can add value, but each has a separate funding source, product rule and accounting treatment.</p><p>Card economics differ by portfolio, transaction type and funding mix. The pilot therefore models contribution at cohort and category level rather than applying one value rate to all payment volume. It also distinguishes spend shifted from another bank, genuinely new spend, spend that would have happened on the same card anyway and transactions that are uneconomic after benefit cost. Loyalty economics follow the same discipline: points redeemed are not free value, and unused balances are not a reason to create a weak customer proposition.</p><p>Merchant economics need an equally explicit view. A merchant may fund a benefit because the bank supplies qualified demand, lowers acquisition cost or improves conversion in a priority category. The contract should define the event that earns funding, how returns reverse it and when settlement occurs. Eligible instalment or financing routes can improve affordability and basket size, but only through existing credit policy, disclosure and underwriting. The commerce layer presents permitted value; it does not invent a new approval path.</p><p>The deductions are material. Customer benefit, acquisition, platform integration, service, fraud, disputes, returns, reward liability, settlement and the fixed team required to run the model all reduce contribution. A programme can report large attributed spend and still destroy value if those costs remain outside the commercial view.</p></div></header>${economicsWaterfall()}<div class="p-decision-table"><div class="head"><span>Line</span><span>Calculation</span><span>Management use</span></div><div><b>Eligible demand</b><span>Eligible customers × covered intent</span><span>Defines the reachable cohort</span></div><div><b>Attributed spend</b><span>Handoffs × conversion × basket × frequency</span><span>Shows activity connected to the journey</span></div><div><b>Incremental spend</b><span>Exposed spend less control and baseline</span><span>Tests behavioural lift</span></div><div><b>Gross value</b><span>Card + merchant + loyalty or finance contribution</span><span>Combines funded value pools</span></div><div><b>Variable cost</b><span>Benefit + acquisition + service + risk + settlement</span><span>Shows cost created by the cohort</span></div><div><b>Net contribution</b><span>Gross value less variable and platform cost</span><span>Determines whether to scale</span></div></div></div></section>
  <section class="p-case-section p-case-dark" id="architecture"><div class="p-shell"><header class="p-case-heading">${label("Technology, data and AI")}<h2>Use existing bank capabilities and connect them through controlled interfaces.</h2><div><p>The mobile app or authenticated web channel captures intent. API services call card, loyalty, offer and approved finance systems. A merchant gateway holds offer and handoff data without copying the merchant's full catalogue into the bank. An event layer connects intent, eligibility, offer view, merchant handoff, authorization, return and settlement.</p><p>A customer consent ledger records purpose, scope and withdrawal. Tokenized handoff IDs reduce the personal data shared with merchants. Card, loyalty and credit systems remain authoritative for financial facts. Merchant systems remain authoritative for product, price, stock, fulfilment and returns.</p></div></header>${bankArchitecture()}${aiDecisioning()}<div class="p-ai-rights"><div><span>AI may</span><b>Rank permitted value</b><b>Explain a recommendation</b><b>Detect service or settlement exceptions</b><b>Prepare scenario evidence</b></div><div><span>AI may not</span><b>Approve credit</b><b>Create product eligibility</b><b>Change rewards liability</b><b>Override consent or policy</b></div><div><span>Human authority</span><b>Approve policy and new data</b><b>Suppress merchants or campaigns</b><b>Resolve consequential exceptions</b><b>Release the next scale gate</b></div></div></div></section>
  <section class="p-case-section p-case-light" id="operating-model"><div class="p-shell"><header class="p-case-heading">${label("Operating model and governance")}<h2>One product owner coordinates the journey; specialist owners retain regulated authority.</h2><div><p>The proposition needs one accountable product owner, one pilot scorecard and one exception queue. Cards, loyalty, merchant partnerships, data, technology, risk, compliance, finance and customer care keep their specialist responsibilities, but they work through a shared operating cadence.</p><p>Merchant operations manage offer readiness, service failures and funding files. Attribution and settlement operations reconcile transactions, returns, rewards and merchant obligations. Customer care sees the same eligibility and offer evidence shown to the customer. Material model changes, new data features, new financial products or wider cohorts require approval and a tested rollback path.</p><p>Governance has to separate commercial optimization from regulated authority. The product team can propose a ranking objective, merchant mix or campaign threshold. Risk and product owners approve eligibility and credit rules. Data governance approves purpose, features and retention. Finance approves funding recognition and the treatment of reversals. A steering group reviews the pilot as one commercial system, but it cannot blur those accountabilities. This keeps speed at the working level while preserving named ownership for customer, financial and model consequences.</p></div></header>${bankOperatingModel()}<div class="p-governance-matrix"><div class="head"><span>Decision</span><span>Accountable owner</span><span>Control</span></div><div><b>Offer eligibility</b><span>Cards and loyalty product</span><span>Apply approved product and campaign rules</span></div><div><b>Offer ranking</b><span>Commerce product</span><span>Rank eligible options and show reason codes</span></div><div><b>Finance approval</b><span>Credit and risk</span><span>Use existing underwriting and affordability policy</span></div><div><b>Retail transaction</b><span>Merchant</span><span>Own price, checkout, delivery and returns</span></div><div><b>Attribution and funding</b><span>Finance and loyalty operations</span><span>Reconcile events, returns and merchant funding</span></div><div><b>Model change</b><span>Data and model governance</span><span>Approve features, monitoring and rollback</span></div></div></div></section>
  <section class="p-case-section p-case-dark" id="roadmap"><div class="p-shell"><header class="p-case-heading">${label("MVP and scale roadmap")}<h2>The first 90 days are an evidence programme.</h2><div><p>Days 0 to 30 establish categories, anchor merchants, eligible cohorts, consent, attribution policy, funding treatment and the executive scorecard. No customer pilot begins while returns, reward reversal or merchant settlement remain ambiguous.</p><p>Days 31 to 60 build the narrow journey, offer feed, eligibility calls, event IDs, operator view and reconciliation file. Employee testing proves that ineligible value is suppressed, customer care can read the evidence and returns reverse correctly. Days 61 to 90 run a limited customer cohort with weekly stop, narrow or continue decisions.</p><p>Months 4 to 12 depend on evidence. New categories, merchants, finance routes or self-service enter only when contribution, service quality, consent and operational control remain inside agreed thresholds.</p></div></header>${bankRoadmap()}</div></section>
  <section class="p-case-section p-case-light" id="impact"><div class="p-shell"><header class="p-case-heading">${label("Measurement and modeled impact")}<h2>The scorecard distinguishes engagement, attribution and incrementality.</h2><div><p>The executive view starts with eligible demand, then follows the event chain through intent, offer view, merchant handoff, completed transaction and repeat behaviour. It pairs those activity measures with service, control and economics. Incremental card spend, measured against a control, is the central commercial signal. Total attributed spend is not a substitute.</p><p>The business case should be expressed as a range. A base case models eligible customers, covered intent, conversion, basket, frequency and control lift. A downside case assumes lower incrementality, more cannibalization of existing spend, higher service cost and slower merchant funding recovery. If the economics work only under optimistic attribution, the pilot should stop or remain narrow.</p></div></header>${kpiCockpit()}<div class="p-impact-grid"><div class="p-impact-statement"><span>Modeled business impact</span><p>${esc(item.impact)}</p><small>No achieved bank revenue, adoption or uplift is claimed.</small></div><div class="p-risk-register"><h3>Risks that can invalidate the case</h3><span><b>Consent</b>Intent data used outside its approved purpose</span><span><b>False incrementality</b>Existing spend credited to the programme</span><span><b>Merchant service</b>Relevant offer followed by poor stock, fulfilment or returns</span><span><b>Funding leakage</b>Benefits, reversals and merchant obligations do not reconcile</span><span><b>Model drift</b>Ranking concentration or bias grows without commercial cause</span><span><b>Economics</b>Reward and operating cost exceed incremental value</span></div></div><div class="p-takeaways"><span>Enter at declared intent.</span><span>Resolve eligibility before ranking.</span><span>Keep retail responsibility with the merchant.</span><span>Measure incrementality against controls.</span><span>Reconcile before scaling.</span></div></div></section>`;
}

const commerceCommandUi = () => `<div class="p-ai-ui p-commerce-ui" aria-label="AI Commerce Command Center product concept"><div class="p-ai-ui-top"><div><i></i><i></i><i></i></div><span>Commerce Command</span><small>09:42 · Live operating view</small></div><div class="p-commerce-ui-grid"><aside><strong>Command center</strong><span class="active">Overview</span><span>Orders</span><span>Inventory</span><span>Sellers</span><span>Customer care</span><span>Finance</span><div><small>Control mode</small><b>Supervised</b></div></aside><main><header><div><small>Exceptions requiring a decision</small><strong>12</strong></div><div><small>Value at risk</small><strong>Review</strong></div><div><small>Actions pending</small><strong>4</strong></div></header><section class="p-command-chart"><div class="p-chart-title"><span>Commerce health</span><small>Orders · service · contribution</small></div><div class="p-chart-bars"><i style="--h:38%"></i><i style="--h:54%"></i><i style="--h:49%"></i><i style="--h:73%"></i><i style="--h:67%"></i><i style="--h:82%"></i><i style="--h:75%"></i><i style="--h:88%"></i></div></section><section class="p-command-action"><div><small>Priority exception</small><strong>Seller payout conflicts with fulfilment evidence</strong><p>Five orders show completed payment but unresolved delivery status.</p></div><div><span>Recommended</span><b>Hold payout and request delivery evidence</b><button>Approve action</button></div></section></main></div></div>`;

const careerRunwayUi = () => `<div class="p-ai-ui p-runway-ui" aria-label="Career Runway AI product interface concept"><div class="p-ai-ui-top"><div><i></i><i></i><i></i></div><span>Career Runway</span><small>Private scenario</small></div><div class="p-runway-grid"><aside><span>Career DNA</span><span class="active">Runway</span><span>Scenarios</span><span>Decision view</span></aside><main><header><small>Decision runway</small><h4>Compare the choice with the cash reality.</h4></header><div class="p-runway-chart"><span class="base">Current path</span><span class="scenario">Scenario</span><svg viewBox="0 0 640 190" aria-hidden="true"><path class="grid" d="M0 25H640 M0 75H640 M0 125H640 M0 175H640"/><path class="line-base" d="M0 40 C120 48,180 54,260 66 S410 92,640 116"/><path class="line-scenario" d="M0 40 C100 61,170 89,245 127 S430 142,640 78"/></svg></div><div class="p-runway-cards"><div><span>Cash runway</span><strong>Deterministic</strong><small>Calculated from entered financial facts</small></div><div><span>Trade-off</span><strong>Explainable</strong><small>Assumptions shown beside each scenario</small></div><div><span>Decision</span><strong>Human-owned</strong><small>The product supports the choice</small></div></div></main></div></div>`;

const aeoFindUi = () => `<div class="p-ai-ui p-aeo-ui" aria-label="AEOFind product interface concept"><div class="p-ai-ui-top"><div><i></i><i></i><i></i></div><span>AEOFind</span><small>Answer visibility diagnostic</small></div><div class="p-aeo-grid"><aside><strong>Commercial intents</strong><span class="active">Category questions</span><span>Brand comparisons</span><span>Purchase criteria</span><span>Service questions</span></aside><main><div class="p-aeo-score"><span>Answer coverage</span><strong>Evidence gaps</strong><i></i></div><div class="p-aeo-table"><div class="head"><span>Intent</span><span>Coverage</span><span>Evidence</span><span>Priority</span></div><div><b>Category selection</b><span class="medium">Partial</span><span>Weak</span><strong>High</strong></div><div><b>Price and value</b><span class="low">Missing</span><span>None</span><strong>High</strong></div><div><b>Service comparison</b><span class="good">Present</span><span>Strong</span><strong>Medium</strong></div><div><b>Purchase location</b><span class="medium">Partial</span><span>Mixed</span><strong>Medium</strong></div></div></main></div></div>`;

const agentArchitecture = () => figure(1, "Enterprise AI workflow architecture", `<div class="p-agent-architecture"><div class="p-agent-row inputs"><span>Approved knowledge</span><span>Live operational APIs</span><span>Event stream</span><span>User context and consent</span></div><div class="p-agent-row orchestration"><strong>Workflow and agent orchestration</strong><span>Task scope</span><span>Tool permissions</span><span>Policy</span><span>State</span></div><div class="p-agent-row action"><span>Retrieve</span><span>Analyze</span><span>Recommend</span><span>Request approval</span><span>Execute</span></div><div class="p-agent-row controls"><strong>Control plane</strong><span>Identity</span><span>Audit</span><span>Evaluation</span><span>Cost</span><span>Rollback</span></div><div class="p-agent-row outcomes"><span>Customer service</span><span>Commerce operations</span><span>Finance workflows</span><span>Management decisions</span></div></div>`, "Retrieval supplies approved knowledge. APIs supply facts that change. Agents act only through named tools and permissions.", "p-exhibit-dark");

export function pilotAi({ useCases }) {
  return `<section class="p-hero p-ai-hero"><div class="p-shell p-ai-hero-grid"><div>${label("AI & Transformation")}<h1>Operational AI,<br>under control.</h1><p>Products and enterprise workflows built around reliable facts, bounded authority and measurable business economics.</p><div class="p-hero-actions">${arrow("#products", "Product showcase", "p-button p-button-light")}${arrow("#architecture", "Architecture", "p-button p-button-ghost")}</div></div><aside class="p-ai-hero-orbit" aria-label="AI operating model"><div class="orbit-center">AI<br>workflow</div><span class="orbit-one">Evidence</span><span class="orbit-two">Policy</span><span class="orbit-three">Human authority</span><span class="orbit-four">Audited action</span></aside></div></section>
  <section class="p-ai-principles"><div class="p-shell"><span><b>01</b>Start with the operating decision</span><span><b>02</b>Separate knowledge from live facts</span><span><b>03</b>Give agents narrow tools</span><span><b>04</b>Keep consequential authority named</span><span><b>05</b>Measure business value and failure</span></div></section>
  <section class="p-product-showcase" id="products"><article class="p-product-chapter p-product-command"><div class="p-shell"><header>${label("Product 01 · In development")}<h2>AI Commerce Command Center</h2><p>A supervised control layer across catalogue, orders, sellers, inventory, customer care and finance. It pulls operating signals into one exception queue, prepares an evidence-backed recommendation and asks for approval before consequential action.</p><div class="p-product-meta"><span><b>Problem</b>Signals are fragmented across commerce systems</span><span><b>Decision</b>Which exception needs action now</span><span><b>Authority</b>Human approval for money, customer and seller consequence</span></div>${arrow("/ai-commerce", "Open the product case", "p-link p-link-light")}</header>${commerceCommandUi()}</div></article>
  <article class="p-product-chapter p-product-runway"><div class="p-shell"><header>${label("Product 02 · Live")}<h2>Career Runway AI</h2><p>A private decision tool that connects a career choice to financial runway and personal trade-offs. Deterministic calculations keep the money model stable. AI helps structure scenarios and explain the assumptions without taking the decision away from the user.</p><div class="p-product-meta"><span><b>Problem</b>Career decisions are discussed without the cash reality</span><span><b>Decision</b>Which path remains viable under different assumptions</span><span><b>Authority</b>The user owns the final choice</span></div>${arrow("/career-runway", "Open the product case")}</header>${careerRunwayUi()}</div></article>
  <article class="p-product-chapter p-product-aeo"><div class="p-shell"><header>${label("Product 03 · Product concept")}<h2>AEOFind</h2><p>A diagnostic product for finding gaps in how AI answer engines cover commercially important questions. It starts with a fixed intent set, tests answer coverage and evidence, then turns weak or missing coverage into a prioritized content and authority plan.</p><div class="p-product-meta"><span><b>Problem</b>Visibility reports do not explain answer-level gaps</span><span><b>Decision</b>Which intent and evidence gap deserves action</span><span><b>Authority</b>People approve the source and publication plan</span></div>${arrow("/use-cases/aeofind", "Open the product case", "p-link p-link-light")}</header>${aeoFindUi()}</div></article></section>
  <section class="p-case-section p-case-dark" id="architecture"><div class="p-shell"><header class="p-case-heading">${label("Technology architecture")}<h2>Knowledge, live facts and authority are separate layers.</h2><div><p>Retrieval is useful for approved policy, procedures and product knowledge. It is not a substitute for live stock, price, account, order or payment facts. Operational agents usually need both: retrieve the relevant rule, query the source system and apply the permission attached to the task.</p><p>The control plane matters as much as the model. Identity, tool permissions, audit, evaluation, cost and rollback determine whether an agent can move from preparing work to taking action. Wider authority is earned through observed accuracy, service quality and clean recovery from failure.</p></div></header>${agentArchitecture()}<div class="p-authority-ladder"><div><span>Level 1</span><b>Read</b><p>Summarize evidence from approved sources.</p></div><div><span>Level 2</span><b>Prepare</b><p>Draft a response, action or scenario for review.</p></div><div><span>Level 3</span><b>Recommend</b><p>Rank permitted options with reasons and confidence.</p></div><div><span>Level 4</span><b>Execute with approval</b><p>Use a named tool after a person approves.</p></div><div><span>Level 5</span><b>Bounded automation</b><p>Act inside policy, value and rollback limits.</p></div></div></div></section>
  <section class="p-section p-ai-cases"><div class="p-shell"><header class="p-section-head"><div>${label("Transformation cases")}<h2>AI inside commercial and operating workflows.</h2></div><p>The technology belongs inside the process, data and decision rights of the business. It is not presented as a separate innovation layer.</p></header><div class="p-ai-case-lines">${[
    ["Banking", "Intent and next-best-value", "Eligibility first, AI ranking second", "/use-cases/leading-saudi-bank-commerce-ecosystem"],
    ["Enterprise", "AI and digital transformation practice", "Workflow evidence, approved platforms and governed agents", "/use-cases/enterprise-ai-transformation-practice"],
    ["Commerce", "Operating exception management", "Signals, recommendation, approval and audited action", "/ai-commerce"],
    ["Search", "AI answer visibility", "Commercial intent, evidence coverage and priority action", "/use-cases/aeofind"]
  ].map((row, index) => `<a href="${row[3]}"><span>0${index + 1}</span><small>${row[0]}</small><strong>${row[1]}</strong><p>${row[2]}</p><i aria-hidden="true">↗</i></a>`).join("")}</div></div></section>
  <section class="p-ai-delivery"><div class="p-shell p-ai-delivery-grid"><div>${label("Delivery model")}<h2>From workflow evidence to governed scale.</h2><p>A useful AI programme begins with the process and the value at stake. The first deployment stays narrow enough to evaluate, reverse and govern.</p></div><div class="p-delivery-steps"><span><b>01</b>Choose one decision and baseline its cost</span><span><b>02</b>Connect approved knowledge and live facts</span><span><b>03</b>Define tools, permissions and human authority</span><span><b>04</b>Run a controlled workflow pilot</span><span><b>05</b>Measure accuracy, service, economics and failure</span><span><b>06</b>Expand authority only after the evidence holds</span></div></div></section>`;
}
